package local.audit;
import java.util.*;import java.nio.file.*;
import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.minecraft.core.registries.*;import net.minecraft.resources.Identifier;import net.minecraft.world.item.*;import net.minecraft.world.InteractionHand;import net.minecraft.world.item.component.ChargedProjectiles;import net.minecraft.core.component.DataComponents;
import local.crossarms.runtime.FrenzyState;
@Mod("phase_two_probe") public class FrenzyNativeProbe {
 List<String> lines=new ArrayList<>();int n;void check(boolean ok,String text){if(!ok)throw new AssertionError(text);lines.add("PASS "+text);n++;}
 void command(net.minecraft.server.level.ServerPlayer p,String text){p.level().getServer().getCommands().performPrefixedCommand(p.level().getServer().createCommandSourceStack().withEntity(p).withLevel(p.level()).withPosition(p.position()).withSuppressedOutput(),text);}
 public FrenzyNativeProbe(){NeoForge.EVENT_BUS.addListener(this::start);}
 void start(ServerStartedEvent e){var w=e.getServer().overworld();try{var p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(w);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);command(p,"function crossarms:load");p.getInventory().clearContent();p.getInventory().setItem(1,new ItemStack(Items.ARROW,64));var bow=new ItemStack(Items.CROSSBOW);bow.enchant(w.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).get(Identifier.parse("crossarms:frenzy")).orElseThrow(),1);p.setItemInHand(InteractionHand.MAIN_HAND,bow);var cb=(CrossbowItem)bow.getItem();
  command(p,"scoreboard players set @s frenzy_shots 5");command(p,"scoreboard players set @s frenzy_empty 0");command(p,"scoreboard players set @s HS_delay 2");check(FrenzyState.score(p,"frenzy_shots")==5,"Fixture has partial burst state");cb.use(w,p,InteractionHand.MAIN_HAND);check(!p.isUsingItem(),"Automatic burst gap cannot start premature reload");
  command(p,"scoreboard players set @s frenzy_empty 1");command(p,"scoreboard players set @s frenzy_shots 26");bow.set(DataComponents.CHARGED_PROJECTILES,ChargedProjectiles.ofNonEmpty(List.of(new ItemStack(Items.ARROW))));cb.use(w,p,InteractionHand.MAIN_HAND);check(p.isUsingItem(),"Exhausted loaded crossbow can start full crank");check(!CrossbowItem.isCharged(bow)&&bow.getOrDefault(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().contains("crossarms_pack:reload_ammo"),"Starting exhausted crank safely parks loaded ammunition");cb.onUseTick(w,p,bow,bow.getUseDuration(p)-5);check(FrenzyState.empty(p),"Incomplete crank does not unlock burst");p.stopUsingItem();cb.use(w,p,InteractionHand.MAIN_HAND);cb.onUseTick(w,p,bow,bow.getUseDuration(p)-200);check(!FrenzyState.empty(p),"Full crank unlocks loaded exhausted crossbow");check(CrossbowItem.isCharged(bow),"Full recovery preserves loaded projectile");check(p.getInventory().getItem(1).getCount()==64,"Loaded recovery does not consume duplicate arrow");p.stopUsingItem();
  command(p,"scoreboard players set @s frenzy_empty 1");bow.set(DataComponents.CHARGED_PROJECTILES,ChargedProjectiles.EMPTY);cb.use(w,p,InteractionHand.MAIN_HAND);cb.onUseTick(w,p,bow,bow.getUseDuration(p)-200);check(!FrenzyState.empty(p)&&CrossbowItem.isCharged(bow),"Empty exhausted bow still loads through native crank");check(p.getInventory().getItem(1).getCount()==63,"Native empty reload consumes one arrow");p.stopUsingItem();
  var plain=new ItemStack(Items.CROSSBOW);p.setItemInHand(InteractionHand.MAIN_HAND,plain);((CrossbowItem)plain.getItem()).use(w,p,InteractionHand.MAIN_HAND);check(p.isUsingItem(),"Ordinary crossbow retains native charging");p.stopUsingItem();p.setItemInHand(InteractionHand.MAIN_HAND,bow);
  command(p,"scoreboard players set @s frenzy_empty 1");command(p,"scoreboard players set @s frenzy_shots 26");bow.set(DataComponents.CHARGED_PROJECTILES,ChargedProjectiles.ofNonEmpty(List.of(new ItemStack(Items.FIREWORK_ROCKET))));cb.use(w,p,InteractionHand.MAIN_HAND);check(!p.isUsingItem()&&CrossbowItem.isCharged(bow),"Unsupported loaded firework cannot unlock Frenzy");
  bow.set(DataComponents.CHARGED_PROJECTILES,ChargedProjectiles.ofNonEmpty(List.of(new ItemStack(Items.ARROW))));cb.use(w,p,InteractionHand.MAIN_HAND);p.stopUsingItem();var moved=bow.copy();p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setItemInHand(InteractionHand.OFF_HAND,moved);p.getInventory().setItem(1,ItemStack.EMPTY);cb.use(w,p,InteractionHand.OFF_HAND);check(p.isUsingItem(),"Interrupted stored ammo survives hand and item-stack changes");cb.onUseTick(w,p,moved,moved.getUseDuration(p)-200);check(!FrenzyState.empty(p)&&CrossbowItem.isCharged(moved),"Saved arrow can finish reload without spare inventory ammo");p.stopUsingItem();
  command(p,"scoreboard players set @s frenzy_empty 1");moved.set(DataComponents.CHARGED_PROJECTILES,ChargedProjectiles.EMPTY);var malformed=new net.minecraft.nbt.CompoundTag();malformed.putString("crossarms_pack:reload_ammo","bad");moved.set(DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(malformed));cb.use(w,p,InteractionHand.OFF_HAND);cb.onUseTick(w,p,moved,moved.getUseDuration(p)-200);check(FrenzyState.empty(p),"Malformed recovery data neither crashes nor unlocks Frenzy");p.stopUsingItem();
  for(double speed:new double[]{3,4.5,9}){var velocity=new net.minecraft.world.phys.Vec3(0,0,speed);var desired=new net.minecraft.world.phys.Vec3(1,0,10);var next=net.spell_engine.internals.ArrowAssist.steer(velocity,desired,Math.toRadians(2));double turn=Math.toDegrees(net.spell_engine.internals.ArrowAssist.angle(velocity,next));double want=.25*Math.clamp(speed/3,1,2);check(Math.abs(turn-want)<.001,"Speed-aware turn bound "+speed);check(Math.abs(next.length()-speed)<1e-8,"Steering retains speed "+speed);}
  Files.writeString(Path.of("phase-two-result.txt"),"PASS "+n+" focused Frenzy/steering checks\n");
 }catch(Throwable t){t.printStackTrace();try{Files.writeString(Path.of("phase-two-result.txt"),"FAIL "+t);}catch(Exception ignored){}}finally{try{Files.write(Path.of("phase-two-checks.txt"),lines);}catch(Exception ignored){}e.getServer().halt(false);}}
}
